Object.assign(HE_KEYS,{hazardDamage:"נזק מאזור הסכנה",hazardTicks:"צעדים באזור הסכנה",protectedTicks:"צעדים מוגנים",foodDropped:"מנות מזון שהושארו",foodReturned:"חזרות למזון",foodStolen:"מזון שאבד",cacheCandidates:"מועמדי מטמון",cacheVisits:"ביקורים ליד מטמון",structureCandidates:"מועמדי מבנה"});
Object.assign(HE_VALUES,{"Somik World Research 1.2 Emergence":"Somik World — מחקר 1.2","frozen-research-1.2-emergence":"מחקר 1.2 — עולם קדמון פתוח","A zone in the center is harmful":"אזור סכנה במרכז גורם לנזק"});
function heValue(v){
 if(v===null||v===undefined)return 'לא מוגדר';if(v===true)return 'כן';if(v===false)return 'לא';
 const enums={birth:'לידה',death:'מוות',checkpoint:'נקודת ביקורת',technical_failure:'תקלה טכנית',move:'תנועה',hold:'אחיזה',carry:'נשיאה',release:'שחרור',contact:'קרבה',cluster:'התקבצות',object:'חפץ',resource:'משאב',corpse:'גופה',agent:'סומיק',sexual:'מינית',asexual:'אל־מינית'};
 if(typeof v==='number')return fmt(v,6);
 if(typeof v==='string')return HE_VALUES[v]||enums[v]||HE_KEYS[v]||heText(v.replace(/^(object|resource|corpse):/,m=>enums[m.slice(0,-1)]+':'));
 return String(v);
}
function heReport(data,depth=0){if(!data||typeof data!=='object')return heValue(data);return Object.entries(data).map(([k,v])=>{const label=Array.isArray(data)?'רשומה '+(Number(k)+1):heKey(k);const prefix='  '.repeat(depth)+label+':';return v&&typeof v==='object'?prefix+'\n'+heReport(v,depth+1):prefix+' '+heValue(v);}).join('\n');}
function heError(error){const s=String(error?.message||error||'');console.error(error);if(/checksum|hash mismatch/i.test(s))return 'חתימת הקובץ אינה תואמת; ייתכן שהקובץ נפגם.';if(/quota/i.test(s))return 'אין די מקום באחסון הדפדפן.';if(/abort/i.test(s))return 'הפעולה בוטלה לפני השלמתה.';if(/Save failed/i.test(s))return 'השמירה נכשלה; ההרצה הנוכחית נשמרת בזיכרון.';if(/Invalid archive/i.test(s))return 'הארכיון מכיל אירוע לא תקין.';if(/version|protocol|schema|incompatible/i.test(s))return 'הקובץ אינו תואם לגרסת המנוע או לפרוטוקול.';if(/JSON|Unexpected token|parse/i.test(s))return 'לא ניתן לקרוא את קובץ השמירה; המבנה אינו תקין.';return /[א-ת]/.test(s)&&!/[A-Za-z]/.test(s)?s:'הפעולה נכשלה. פרטי התקלה זמינים ביומן הטכני של הדפדפן.';}
function heTests(t){return (t.ok?'הבדיקות עברו':'נמצאו כשלים')+' · '+t.results.length+' בדיקות\n'+t.results.map((x,i)=>(x.ok?'✓':'✗')+' '+(HE_TESTS[x.name]||'בדיקה '+(i+1))+(x.detail?' — '+heError(x.detail):'')).join('\n');}

const $=id=>document.getElementById(id);
const fmt=(v,d=2)=>v!==null&&v!==undefined&&Number.isFinite(Number(v))?Number(v).toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const pct=(v,d=1)=>Number.isFinite(Number(v))?(Number(v)*100).toFixed(d)+'%':'—';
const nowIso=()=>new Date().toISOString();
let world=null,running=true,speed=100,renderEnabled=true,selectedId=null,brainMode='selected';
let importedEvents=[];
let runMeta={runId:'',createdAt:'',lastSaveAt:'',lastSaveTick:-1,eventSeq:0};
let db=null,lastMetrics=null,lastUiAt=0,lastDrawAt=0,lastAutosaveWall=0,lastAutosaveTick=0,lastPerfAt=performance.now(),ticksSincePerf=0,currentTPS=0,saveInFlight=null;
let livingObserver={runId:'',selectedId:null,lastTick:-1,prev:null,samples:[],events:[],counts:{moves:0,contacts:0,carries:0,holds:0,releases:0,clusters:0},clusterSum:0,clusterSamples:0};
const AUTOSAVE_MS=30000,AUTOSAVE_TICKS=5000,ROLLING_SAVES=5;
const COLORS={agent:'#38bdf8',primary:'#fde047',waste:'#a78bfa',tissue:'#fb923c',object:'#94a3b8',corpse:'#b45309'};

function resetLivingObserver(){livingObserver={runId:runMeta.runId,selectedId:selectedId,lastTick:-1,prev:null,samples:[],events:[],counts:{moves:0,contacts:0,carries:0,holds:0,releases:0,clusters:0},clusterSum:0,clusterSamples:0};}
function torusDelta(a,b,size){let d=a-b;if(d>size/2)d-=size;if(d<-size/2)d+=size;return d;}
function torusDistance(a,b){const dx=torusDelta(a.x,b.x,E.Protocol.world.width),dy=torusDelta(a.y,b.y,E.Protocol.world.height);return Math.hypot(dx,dy);}
function livingEvent(type,text,evidence={}){livingObserver.events.push({tick:world.tick,type,text,evidence});if(livingObserver.events.length>120)livingObserver.events.splice(0,livingObserver.events.length-120);}
function observeLiving(){
  if(!world)return; if(livingObserver.runId!==runMeta.runId||livingObserver.selectedId!==selectedId)resetLivingObserver();
  const a=selectedAgent(); if(!a){livingObserver.lastTick=world.tick;return;}
  if(livingObserver.lastTick===world.tick)return;
  const near=world.agents.filter(x=>x.id!==a.id&&torusDistance(a,x)<=Math.max(28,a.pheno.radius*3.2));
  const cluster=near.length+1, holding=a.holding?`${a.holding.kind}:${a.holding.id}`:null, prev=livingObserver.prev;
  let moved=0;if(prev)moved=torusDistance(a,prev);
  if(prev&&moved>0.35){livingObserver.counts.moves++;if(livingObserver.counts.moves===1||livingObserver.counts.moves%12===0)livingEvent('move',`תנועה של #${a.id}`,{distance:Math.round(moved*100)/100});}
  if(prev&&!prev.holding&&holding){livingObserver.counts.holds++;livingObserver.counts.carries++;livingEvent('hold',`אחיזה ב־${heValue(holding)}`,{kind:a.holding.kind,id:a.holding.id});}
  if(prev&&prev.holding&&holding&&prev.holding===holding){livingObserver.counts.carries++;if(livingObserver.counts.carries===1||livingObserver.counts.carries%15===0)livingEvent('carry',`המשך נשיאה של ${heValue(holding)}`,{ticks:livingObserver.counts.carries});}
  if(prev&&prev.holding&&!holding){livingObserver.counts.releases++;livingEvent('release',`שחרור ${heValue(prev.holding)}`,{releases:livingObserver.counts.releases});}
  if(near.length>0&&(!prev||prev.near===0)){livingObserver.counts.contacts++;livingEvent('contact',`מגע קרוב עם ${near.map(x=>'#'+x.id).slice(0,3).join(', ')}`,{agents:near.map(x=>x.id),radius:Math.round(Math.max(28,a.pheno.radius*3.2))});}
  if(cluster>=3){livingObserver.counts.clusters++;livingObserver.clusterSum+=cluster;livingObserver.clusterSamples++;if(livingObserver.counts.clusters===1||livingObserver.counts.clusters%10===0)livingEvent('cluster',`סביבת קרבה: ${cluster} פרטים`,{localGroup:cluster});}
  livingObserver.samples.push({tick:world.tick,moved,cluster,near:near.length,holding,energy:a.energy,dir:a.dir});if(livingObserver.samples.length>180)livingObserver.samples.shift();
  livingObserver.prev={x:a.x,y:a.y,holding,near:near.length};livingObserver.lastTick=world.tick;
}
function livingLabels(){const c=livingObserver.counts,s=livingObserver.samples;const labels=[];if(c.carries>=3)labels.push({name:'נשיאה חוזרת',evidence:`${c.carries} דגימות נשיאה`});if(c.contacts>=3)labels.push({name:'מגעים חוזרים',evidence:`${c.contacts} מפגשי קרבה`});if(c.clusters>=5&&livingObserver.clusterSamples&&livingObserver.clusterSum/livingObserver.clusterSamples>=3)labels.push({name:'התקבצות יציבה',evidence:`ממוצע ${fmt(livingObserver.clusterSum/livingObserver.clusterSamples,1)} פרטים בסביבה`});if(s.length>=12&&s.filter(x=>x.moved>.35).length>=8)labels.push({name:'תנועה מתמשכת',evidence:`${s.filter(x=>x.moved>.35).length} צעדי תנועה שנמדדו`});return labels;}
function updateLivingUi(){const badges=$('livingBadges'),evidence=$('livingEvidence'),timeline=$('livingTimeline');if(!badges||!evidence||!timeline)return;const a=selectedAgent(),c=livingObserver.counts,s=livingObserver.samples;const strip=$('livingStrip');if(strip){const ev=livingObserver.events.slice(-4).reverse(),cards=strip.querySelectorAll('.storyCard');cards.forEach((card,i)=>card.classList.toggle('active',!!ev[i]||(!a&&i===0)));if(a){const texts=[`סומיק #${a.id} נבחר`,`תנועה: ${c.moves} דגימות`,`מגעים: ${c.contacts} · נשיאה: ${c.carries}`,livingLabels()[0]?.name||'ממתינים לדפוס חוזר'];cards.forEach((card,i)=>{const b=card.querySelector('b'),sp=card.querySelector('span');if(b)b.textContent=`${i+1}. ${texts[i]}`;if(sp)sp.textContent=ev[i]?ev[i].text:'תצפית בלבד · ראיות גולמיות בלבד';});}}badges.innerHTML=a?livingLabels().map(x=>`<span class="livingBadge">${x.name}<small>${x.evidence}</small></span>`).join('')||'<span class="small">עדיין אין דפוס חוזר עם מספיק ראיות.</span>':'<span class="small">בחר סומיק כדי להתחיל תצפית.</span>';const avg=s.length?livingObserver.clusterSum/Math.max(1,livingObserver.clusterSamples):0;evidence.innerHTML=rowsHtml([['נבחר',a?'#'+a.id:'—'],['דגימות',s.length],['תנועה',c.moves],['מגעים',c.contacts],['אחיזות / נשיאות',`${c.holds} / ${c.carries}`],['שחרורים',c.releases],['ממוצע קבוצה מקומית',avg?fmt(avg,1):'—']]);timeline.innerHTML=livingObserver.events.slice(-28).reverse().map(e=>`<div class="livingEvent"><div class="t">צעד ${fmt(e.tick,0)} · ${heValue(e.type)}</div><b>${e.text}</b><span>${Object.entries(e.evidence||{}).map(([k,v])=>`${heKey(k)}: ${Array.isArray(v)?v.join(','):heValue(v)}`).join(' · ')}</span></div>`).join('')||'<div class="small">הציר יתמלא כאשר הנבחר ינוע או ייצור מגעים.</div>';}

function makeRunId(seed){return `R11-${seed}-${Date.now()}-${crypto.randomUUID?.()||Math.random().toString(36).slice(2)}`;}
function treatmentName(){return world?.treatment?.reproductionMode==='sexual'?'אבולוציה פתוחה — רבייה מינית':'Control';}

function openDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open('somik-world-research-1-2',2);r.onupgradeneeded=()=>{const d=r.result,tx=r.transaction;let ss;if(!d.objectStoreNames.contains('snapshots'))ss=d.createObjectStore('snapshots',{keyPath:'key'});else ss=tx.objectStore('snapshots');if(!ss.indexNames.contains('savedAt'))ss.createIndex('savedAt','savedAt');if(!ss.indexNames.contains('runId'))ss.createIndex('runId','runId');let es;if(!d.objectStoreNames.contains('events'))es=d.createObjectStore('events',{keyPath:['runId','seq']});else es=tx.objectStore('events');if(!es.indexNames.contains('runId'))es.createIndex('runId','runId');if(!es.indexNames.contains('type'))es.createIndex('type','type');if(!es.indexNames.contains('child'))es.createIndex('child','child');if(!es.indexNames.contains('runChild'))es.createIndex('runChild',['runId','child']);if(!es.indexNames.contains('runType'))es.createIndex('runType',['runId','type']);if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta',{keyPath:'key'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function txDone(tx){return new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('IDB abort'));});}
function compactEvent(ev){
  if(!['birth','death','checkpoint','technical_failure'].includes(ev.type))return null;
  const out={...ev};delete out.runId;delete out.seq;return out;
}
async function saveNow(reason='manual'){
  if(!world)return false;
  if(saveInFlight){await saveInFlight;return saveNow(reason);}
  if(!db){lastAutosaveWall=Date.now();lastAutosaveTick=world.tick;return false;}
  const target=world,meta={...runMeta},sourceCount=target.eventBuffer.length,historyCount=importedEvents.length;
  const events=[...importedEvents,...target.eventBuffer.slice(0,sourceCount).map(compactEvent).filter(Boolean)];
  const savedAt=nowIso(),tick=target.tick,key=`${meta.runId}:${String(tick).padStart(14,'0')}`;
  const snapshot=JSON.parse(JSON.stringify(target.dump()));snapshot.eventBuffer=[];
  const savedMeta={...meta,lastSaveAt:savedAt,lastSaveTick:tick,eventSeq:meta.eventSeq+events.length};
  const record={key,runId:meta.runId,seed:target.seed,tick,savedAt,reason,engineHash:E.ENGINE_HASH,
    protocolHash:E.PROTOCOL_HASH,stateHash:target.stateHash(),snapshotHash:E.snapshotHash(snapshot),
    state:snapshot,appMeta:{...savedMeta,selectedId}};
  saveInFlight=(async()=>{try{
    // World, event sequence and event archive commit together or not at all.
    const tx=db.transaction(['events','snapshots','meta'],'readwrite'),done=txDone(tx);
    let seq=meta.eventSeq;for(const ev of events)tx.objectStore('events').put({...ev,runId:meta.runId,seq:++seq});
    tx.objectStore('snapshots').put(record);tx.objectStore('meta').put({key:'latest',snapshotKey:key});await done;
    target.eventBuffer.splice(0,sourceCount);importedEvents.splice(0,historyCount);
    if(world===target&&runMeta.runId===meta.runId){Object.assign(runMeta,savedMeta);lastAutosaveWall=Date.now();lastAutosaveTick=tick;
      $('saveStatus').className='saveOk';$('saveStatus').textContent=`✓ נשמר — ${new Date(savedAt).toLocaleTimeString('he-IL')} · צעד ${fmt(tick,0)}`;}
    try{await pruneSnapshots(meta.runId);}catch(err){console.warn('Snapshot pruning:',err);}
    refreshArchiveUi();return true;
  }catch(err){lastAutosaveWall=Date.now();lastAutosaveTick=target.tick;
    $('saveStatus').className='saveWarn';$('saveStatus').textContent='⚠ השמירה נכשלה. ייצא קובץ גיבוי: '+heError(err);return false;
  }finally{saveInFlight=null;}})();return saveInFlight;
}
async function pruneSnapshots(runId){const tx=db.transaction('snapshots','readwrite'),idx=tx.objectStore('snapshots').index('runId'),req=idx.getAll(IDBKeyRange.only(runId));const rows=await reqPromise(req);rows.sort((a,b)=>b.tick-a.tick);for(const r of rows.slice(ROLLING_SAVES))tx.objectStore('snapshots').delete(r.key);await txDone(tx);}
function reqPromise(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function latestSnapshot(){if(!db)return null;const tx=db.transaction('snapshots'),idx=tx.objectStore('snapshots').index('savedAt'),req=idx.openCursor(null,'prev');return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result?.value||null);req.onerror=()=>reject(req.error);});}
async function loadSnapshotRecord(rec){if(rec.snapshotHash&&E.snapshotHash(rec.state)!==rec.snapshotHash)throw new Error('Snapshot checksum mismatch');const loaded=E.World.load(rec.state);if(rec.stateHash&&loaded.stateHash()!==rec.stateHash)throw new Error('Scientific state checksum mismatch');world=loaded;importedEvents=[];runMeta={...rec.appMeta,lastSaveAt:rec.savedAt,lastSaveTick:rec.tick,eventSeq:rec.appMeta?.eventSeq||0};selectedId=rec.appMeta?.selectedId||null;resetLivingObserver();running=!world.extinct&&!world.technicalFailure;speed=Number($('speedSel').value)||100;lastAutosaveWall=Date.now();lastAutosaveTick=world.tick;updateRunIdentity();updatePauseUi();fullRefresh();}
async function loadSnapshotByKey(key){const tx=db.transaction('snapshots'),rec=await reqPromise(tx.objectStore('snapshots').get(key));if(!rec)return;const was=running;running=false;try{
  if(!await saveNow('before-load'))throw new Error('Save failed; current run retained');
  const entries=await getAllEvents(rec.runId);await loadSnapshotRecord(rec);running=false;
  const sourceRunId=runMeta.runId;runMeta={...runMeta,runId:makeRunId(world.seed),sourceRunId,createdAt:nowIso(),eventSeq:0,lastSaveTick:-1,lastSaveAt:''};
  importedEvents=entries.filter(e=>e.seq<=(rec.appMeta?.eventSeq||0)).map(compactEvent).filter(Boolean);
  await saveNow('fork-from-snapshot');updateRunIdentity();updatePauseUi();
}catch(err){running=was;updatePauseUi();alert(heError(err));}}
async function countEvents(){if(!db||!runMeta.runId)return 0;const tx=db.transaction('events'),idx=tx.objectStore('events').index('runId');return await reqPromise(idx.count(IDBKeyRange.only(runMeta.runId)));}
async function getAllEvents(runId=runMeta.runId){if(!db)return[];const tx=db.transaction('events'),idx=tx.objectStore('events').index('runId');return await reqPromise(idx.getAll(IDBKeyRange.only(runId)));}
async function listRuns(){if(!db)return[];const tx=db.transaction('snapshots'),rows=await reqPromise(tx.objectStore('snapshots').getAll());const best=new Map();for(const r of rows){const x=best.get(r.runId);if(!x||r.tick>x.tick)best.set(r.runId,r);}return[...best.values()].sort((a,b)=>b.savedAt.localeCompare(a.savedAt));}
async function refreshStorageUi(){if(!$('storageInfo'))return;try{const est=await navigator.storage?.estimate?.(),persisted=await navigator.storage?.persisted?.();const usage=est?.usage??0,quota=est?.quota??0;$('storageInfo').innerHTML=rowsHtml([['אחסון מתמשך',persisted?'כן':'לא / לא הובטח'],['שימוש',usage?fmt(usage/1048576,2)+' מגה־בייט':'—'],['מכסת אחסון',quota?fmt(quota/1048576,1)+' מגה־בייט':'—'],['שימוש מתוך המכסה',quota?pct(usage/quota,2):'—']]);}catch{$('storageInfo').innerHTML=rowsHtml([['ממשק אחסון','לא זמין']]);}}
async function requestPersistentStorage(){try{const ok=await navigator.storage?.persist?.();await refreshStorageUi();$('saveStatus').className=ok?'saveOk':'saveWarn';$('saveStatus').textContent=ok?'✓ אחסון מתמשך אושר':'⚠ הדפדפן לא הבטיח אחסון מתמשך; שמירה אוטומטית עדיין פעיל';}catch(err){$('saveStatus').className='saveWarn';$('saveStatus').textContent='⚠ בקשת אחסון מתמשך נכשלה: '+heError(err);}}
async function birthRecordFor(agentId){if(!db||!runMeta.runId)return null;const tx=db.transaction('events'),idx=tx.objectStore('events').index('runChild');return await reqPromise(idx.get([runMeta.runId,Number(agentId)]));}
async function reconstructAncestry(){const root=selectedAgent();if(!root){$('ancestryTable').innerHTML='<tr><td colspan="6">בחר סומיק.</td></tr>';return;}const maxDepth=Math.max(1,Math.min(30,Number($('ancestryDepth').value)||8)),seen=new Set(),queue=[{id:root.id,depth:0}],rows=[];while(queue.length&&rows.length<1000){const cur=queue.shift();if(seen.has(cur.id)||cur.depth>maxDepth)continue;seen.add(cur.id);let rec=world.lineageRecent.get(cur.id)||null;if(!rec){const ev=await birthRecordFor(cur.id);if(ev)rec={id:ev.child,parentA:ev.parentA,parentB:ev.parentB,generation:ev.generation,genomeHash:ev.genomeHash};}if(!rec&&cur.id===root.id)rec={id:root.id,parentA:root.parentA,parentB:root.parentB,generation:root.generation,genomeHash:E.genomeHash(root.genome)};if(!rec){rows.push({depth:cur.depth,id:cur.id,generation:'—',parentA:'—',parentB:'—',genomeHash:'ארכיון לא זמין'});continue;}rows.push({depth:cur.depth,...rec});if(cur.depth<maxDepth){if(rec.parentA)queue.push({id:rec.parentA,depth:cur.depth+1});if(rec.parentB)queue.push({id:rec.parentB,depth:cur.depth+1});}}$('ancestryTable').innerHTML=rows.map(r=>`<tr><td>${r.depth}</td><td>${r.id}</td><td>${r.generation??'—'}</td><td>${r.parentA||'—'}</td><td>${r.parentB||'—'}</td><td class="mono">${r.genomeHash||'—'}</td></tr>`).join('')||'<tr><td colspan="6">אין נתונים.</td></tr>';}

function newWorld(seed=1){importedEvents=[];seed=Math.max(1,Number(seed)>>>0);world=new E.World({seed,hazardEnabled:true,cacheEnabled:true});runMeta={runId:makeRunId(seed),createdAt:nowIso(),lastSaveAt:'',lastSaveTick:-1,eventSeq:0};selectedId=null;resetLivingObserver();running=true;lastAutosaveWall=Date.now();lastAutosaveTick=0;$('seedInput').value=seed;updateRunIdentity();updatePauseUi();fullRefresh();saveNow('new-run');}
function updateRunIdentity(){$('runIdLabel').textContent=runMeta.runId||'—';$('protocolBadge').textContent=`${E.PROTOCOL_ID} · ${E.PROTOCOL_HASH}`;$('identityRows').innerHTML=rowsHtml([['מזהה הרצה',runMeta.runId],['ערך אתחול',world?.seed],['פרוטוקול',E.PROTOCOL_ID],['חתימת הפרוטוקול',E.PROTOCOL_HASH],['חתימת המנוע',E.ENGINE_HASH],['חתימת תנאי הניסוי',world?.protocolVariantHash],['גנום המייסד',world?.ancestorHash]]);}
function updatePauseUi(){$('pauseBtn').textContent=running?'⏸ עצור':'▶ הפעל';$('runStatus').textContent=world?.extinct?'נכחד':world?.technicalFailure?'תקלה':running?'רץ':'עצור';$('runStatus').className='statusPill '+(running?'run':'stop');}

function rowsHtml(rows){return rows.map(([a,b,cls])=>`<div class="row"><span>${heText(a)}</span><b class="${cls||''}">${b??'—'}</b></div>`).join('');}
function selectedAgent(){return world?.agents.find(a=>a.id===selectedId)||null;}
function currentGenome(){return brainMode==='founder'?world?.ancestorGenome:selectedAgent()?.genome||world?.ancestorGenome;}

function updateMetrics(){if(!world)return;const m=world.metrics();lastMetrics=m;$('kPop').textContent=fmt(m.population,0);$('kGen').textContent=fmt(m.medianGeneration,1);$('kBirth').textContent=fmt(m.births,0);$('kTick').textContent=fmt(m.tick,0);$('kFitness').textContent=fmt(m.reproductionRatePer1000MatureTicks,3);$('kGenDist').textContent=fmt(m.meanGeneticDistance,4);$('stateHashLabel').textContent=world.stateHash();
  $('primaryRows').innerHTML=rowsHtml([['צאצאים עד גיל קבוע',fmt(m.meanOffspringFixedAge,3)],['התרבו עד גיל קבוע',pct(m.reproducedFixedAgeFraction)],['מספר צאצאים לאורך החיים של חיים שהסתיימו',fmt(m.completedLRS,3)],['התרבו לפחות פעם אחת',pct(m.completedReproducedFraction)],['רבייה / 1000 צעדי בגרות',fmt(m.reproductionRatePer1000MatureTicks,4)],['הכחדה',m.extinct?'כן':'לא']]);
  $('secondaryRows').innerHTML=rowsHtml([['אנרגיה ממוצעת',fmt(m.meanEnergy,2)],['בריאות ממוצעת',fmt(m.meanHealth,3)],['גיל ממוצע',fmt(m.meanAge,1)],['לידות / מוות',`${fmt(m.births,0)} / ${fmt(m.deaths,0)}`],['משאבים חופשיים',fmt(m.resources,0)],['גופות',fmt(m.corpses,0)]]);
  $('exploreRows').innerHTML=rowsHtml([['מרחק גנטי מהאב',fmt(m.meanGeneticDistance,5)],['מגוון גנטי',fmt(m.geneticDiversity,5)],['גנומים ייחודיים במדגם',pct(m.uniqueGenomeFraction)],['שיעור הגנום הנפוץ',pct(m.topGenomeShare)],['מורכבות המוח',fmt(m.brainComplexity,2)],['חדשנות',fmt(m.phenotypeNovelty,4)],['אשכולות תצפיתיים',fmt(m.observerClusters,0)]]);
  updateSelectedSide();updateEvolutionUi();updateEcologyUi();updateArchiveSimple();
}
function signedSensorHtml(label,value){const v=Number(value)||0,p=Math.max(0,Math.min(100,(v+1)*50));return `<div class="sensorItem"><div class="sensorLine"><span>${label}</span><b>${v.toFixed(3)}</b></div><div class="sensorBar signed"><i style="width:${p}%"></i></div></div>`;}
function unitSensorHtml(label,value){const v=Math.max(0,Math.min(1,Number(value)||0)),p=v*100;return `<div class="sensorItem"><div class="sensorLine"><span>${label}</span><b>${v.toFixed(3)}</b></div><div class="sensorBar"><i style="width:${p}%"></i></div></div>`;}
function updateClassicInspector(a){
  const badge=$('selectedQuickBadge'),sensors=$('selectedSensors'),actions=$('selectedActions');
  if(!a){if(badge)badge.textContent='לחץ על סומיק';if(sensors)sensors.innerHTML='<div class="small">בחר סומיק.</div>';if(actions)actions.innerHTML='<div class="small">בחר סומיק.</div>';drawBrainMini();return;}
  if(badge)badge.textContent='#'+a.id;
  if(sensors){const inp=a.lastInputs||{};let html=signedSensorHtml('אנרגיה',inp.energy)+signedSensorHtml('בריאות',inp.health)+signedSensorHtml('מגע',inp.touch)+signedSensorHtml('שדה כימי',inp.chemical);a.genome.sensors.forEach((s,i)=>{html+=signedSensorHtml(`חיישן ${i+1} · ${Math.round(s.range)}פיקסלים`,inp['ray:'+s.id]);});sensors.innerHTML=html;}
  if(actions){const o=a.outputs||{};actions.innerHTML=rowsHtml([['מנוע שמאל',fmt(o.left_motor,3)],['מנוע ימין',fmt(o.right_motor,3)],['לסת',fmt(o.jaw,3)],['אחיזה',fmt(o.grip,3)],['פליטה כימית',fmt(o.chemical_emit,3)]]);}
  drawBrainMini();
}
function updateSelectedSide(){const a=selectedAgent();if(!a){$('selectedSide').textContent='לא נבחר סומיק.';$('selectedLabel').textContent='לחץ על סומיק לבחירה';updateClassicInspector(null);return;}const g=a.genome,p=a.pheno;$('selectedLabel').textContent=`סומיק #${a.id} · דור ${a.generation} · גנום ${E.genomeHash(g)}`;$('selectedSide').innerHTML=rowsHtml([['מזהה',a.id],['דור',a.generation],['גיל',fmt(a.age,0)],['אנרגיה',`${fmt(a.energy,1)} / ${fmt(p.energyCapacity,1)}`],['בריאות',fmt(a.health,3)],['צאצאים',a.offspring],['הורים',`${a.parentA||'—'} / ${a.parentB||'—'}`],['חתימה גנטית',E.genomeHash(g),'mono'],['מרחק מהאב',fmt(E.genomeDistance(g,world.ancestorGenome),5)],['גודל גוף',fmt(p.radius,2)],['תאים פנימיים / קשרים',`${g.hidden.length} / ${g.connections.filter(c=>c.enabled).length}`]]);updateClassicInspector(a);}

let trailRun='',trails=new Map();
function visualColor(id){const n=Math.abs(Number(id)||0);return ['#61c9ff','#ffd34d','#ff8a65','#bd8cff','#6ee7b7','#f78fb3'][n%6];}
function drawTerrain(ctx,W,H,sx,sy){
  ctx.fillStyle='#65b947';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='rgba(226,205,112,.25)';for(let i=0;i<18;i++){const x=((i*173+83)%E.Protocol.world.width)*sx,y=((i*97+41)%E.Protocol.world.height)*sy;ctx.fillRect(x,y,75*sx,18*sy);}
  ctx.fillStyle='rgba(255,255,255,.10)';ctx.strokeStyle='rgba(28,93,57,.24)';ctx.lineWidth=1;
  for(let x=0;x<E.Protocol.world.width;x+=64){ctx.beginPath();ctx.moveTo(x*sx,0);ctx.lineTo(x*sx,H);ctx.stroke();}
  for(let y=0;y<E.Protocol.world.height;y+=64){ctx.beginPath();ctx.moveTo(0,y*sy);ctx.lineTo(W,y*sy);ctx.stroke();}
  const hz=E.Protocol.hazard;ctx.fillStyle='rgba(134,48,38,.58)';ctx.fillRect(hz.x*sx,hz.y*sy,hz.w*sx,hz.h*sy);ctx.fillStyle='rgba(255,176,64,.10)';for(let x=hz.x;x<hz.x+hz.w;x+=32){ctx.fillRect(x*sx,0,15*sx,H);}ctx.strokeStyle='rgba(255,182,72,.62)';ctx.lineWidth=2;ctx.strokeRect(hz.x*sx,0,hz.w*sx,H);ctx.fillStyle='rgba(255,235,180,.88)';ctx.font=`${12*(devicePixelRatio||1)}px Arial`;ctx.textAlign='center';ctx.fillText('אזור סכנה — נזק פיזי', (hz.x+hz.w/2)*sx, 20*sy);ctx.textAlign='start';
  // Decorative water basin: visual-only, never read by the engine.
  ctx.fillStyle='#2c9cdb';ctx.beginPath();ctx.moveTo(0,H*.52);ctx.bezierCurveTo(W*.08,H*.43,W*.18,H*.53,W*.24,H*.64);ctx.bezierCurveTo(W*.30,H*.74,W*.19,H*.91,W*.04,H*.87);ctx.lineTo(0,H);ctx.closePath();ctx.fill();
  ctx.strokeStyle='rgba(196,242,255,.34)';ctx.lineWidth=2;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(W*.03,H*(.60+i*.08));ctx.quadraticCurveTo(W*.12,H*(.56+i*.08),W*.22,H*(.62+i*.08));ctx.stroke();}
  function tree(x,y,scale=1){ctx.fillStyle='#75432a';ctx.fillRect((x-5*scale)*sx,(y+7*scale)*sy,10*scale*sx,24*scale*sy);ctx.fillStyle='#1d7d42';ctx.beginPath();ctx.arc(x*sx,(y-4*scale)*sy,23*scale*sx,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3baa4f';ctx.beginPath();ctx.arc((x-12*scale)*sx,(y+2*scale)*sy,16*scale*sx,0,Math.PI*2);ctx.arc((x+12*scale)*sx,(y+1*scale)*sy,17*scale*sx,0,Math.PI*2);ctx.fill();}
  [[55,55,1.2],[170,150,.9],[320,55,1.1],[520,110,1.0],[740,60,1.2],[1030,110,1.1],[1140,300,.9],[980,610,1.15],[760,640,1.1],[410,630,.95],[170,570,1.15]].forEach(t=>tree(...t));
  function rock(x,y,r=18){ctx.fillStyle='#68727b';ctx.beginPath();ctx.moveTo((x-r)*sx,(y+8)*sy);ctx.lineTo((x-r*.65)*sx,(y-r)*sy);ctx.lineTo((x+r*.35)*sx,(y-r*1.12)*sy);ctx.lineTo((x+r)*sx,(y+5)*sy);ctx.lineTo((x+r*.45)*sx,(y+r)*sy);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(255,255,255,.22)';ctx.stroke();}
  [[235,75,25],[1090,500,28],[1080,670,25],[285,520,20],[885,95,18],[620,650,24]].forEach(r=>rock(...r));
}
function drawSomik(ctx,a,sx,sy,selected){const x=a.x*sx,y=a.y*sy,r=Math.max(9,a.pheno.radius*sx*2.15),col=visualColor(a.id);ctx.save();ctx.translate(x,y);ctx.rotate(a.dir||0);if(selected){ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,r+8,0,Math.PI*2);ctx.stroke();}ctx.strokeStyle='rgba(7,45,55,.55)';ctx.lineWidth=1.5;ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(0,0,r*1.15,r*.9,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#17354c';ctx.beginPath();ctx.arc(r*.35,-r*.28,Math.max(1.5,r*.15),0,Math.PI*2);ctx.arc(r*.35,r*.28,Math.max(1.5,r*.15),0,Math.PI*2);ctx.fill();ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-r*.55,-r*.55);ctx.lineTo(-r*.95,-r*1.15);ctx.moveTo(-r*.55,r*.55);ctx.lineTo(-r*.95,r*1.15);ctx.stroke();ctx.restore();}
function drawWorld(){if(!world||!renderEnabled)return;const c=$('world'),ctx=c.getContext('2d'),W=c.width,H=c.height,sx=W/E.Protocol.world.width,sy=H/E.Protocol.world.height;ctx.clearRect(0,0,W,H);drawTerrain(ctx,W,H,sx,sy);
  if($('layerResources').checked)for(const r of world.resources){const x=r.x*sx,y=r.y*sy;ctx.fillStyle=COLORS[r.material]||'#f8d34d';ctx.strokeStyle='rgba(120,40,40,.45)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,Math.max(4,E.Protocol.resources.resourceRadius*sx*1.25),0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(255,255,255,.7)';ctx.beginPath();ctx.arc(x-2*sx,y-2*sy,1.4*sx,0,Math.PI*2);ctx.fill();}
  for(const o of world.objects){const x=o.x*sx,y=o.y*sy,r=o.radius*sx;ctx.fillStyle='#927451';ctx.fillRect(x-r,y-r,r*2,r*2);ctx.fillStyle='rgba(255,255,255,.18)';ctx.fillRect(x-r+2,y-r+2,r*1.5,3);ctx.strokeStyle='#4b3b30';ctx.strokeRect(x-r,y-r,r*2,r*2);}
  if($('layerResources').checked)for(const co of world.corpses){ctx.fillStyle='#75422b';ctx.beginPath();ctx.arc(co.x*sx,co.y*sy,co.radius*sx,0,Math.PI*2);ctx.fill();}
  if(trailRun!==runMeta.runId){trails.clear();trailRun=runMeta.runId;}const alive=new Set(world.agents.map(a=>a.id));for(const id of trails.keys())if(!alive.has(id))trails.delete(id);
  if($('layerTrails').checked){ctx.strokeStyle='rgba(255,255,255,.32)';ctx.lineWidth=1;for(const a of world.agents){const points=trails.get(a.id)||[];if(points.at(-1)?.tick!==world.tick)points.push({x:a.x,y:a.y,tick:world.tick});if(points.length>60)points.shift();trails.set(a.id,points);ctx.beginPath();points.forEach((p,i)=>{const prev=points[i-1];if(!prev||Math.abs(prev.x-p.x)>E.Protocol.world.width/2||Math.abs(prev.y-p.y)>E.Protocol.world.height/2)ctx.moveTo(p.x*sx,p.y*sy);else ctx.lineTo(p.x*sx,p.y*sy);});ctx.stroke();}}
  for(const a of world.agents)drawSomik(ctx,a,sx,sy,a.id===selectedId);
  const sel=selectedAgent();if(sel&&$('raysCheck').checked){ctx.save();ctx.strokeStyle='rgba(255,255,255,.55)';ctx.lineWidth=1;for(const ss of sel.genome.sensors){const ang=sel.dir+ss.angle;ctx.beginPath();ctx.moveTo(sel.x*sx,sel.y*sy);ctx.lineTo((sel.x+Math.cos(ang)*ss.range)*sx,(sel.y+Math.sin(ang)*ss.range)*sy);ctx.stroke();}ctx.restore();}
}
function worldClick(ev){const rect=$('world').getBoundingClientRect(),x=(ev.clientX-rect.left)/rect.width*E.Protocol.world.width,y=(ev.clientY-rect.top)/rect.height*E.Protocol.world.height;let best=null,bd=Infinity;for(const a of world.agents){const d=E.helpers.dist2(x,y,a.x,a.y);if(d<bd){bd=d;best=a;}}if(best&&Math.sqrt(bd)<35){selectedId=best.id;brainMode='selected';fullRefresh();}}

function canvasFit(c){const dpr=Math.min(2,devicePixelRatio||1),rect=c.getBoundingClientRect(),w=Math.max(320,Math.floor(rect.width*dpr)),h=Math.max(180,Math.floor(rect.height*dpr));if(c.width!==w||c.height!==h){c.width=w;c.height=h;}return{ctx:c.getContext('2d'),w,h,dpr};}
function chart(canvas,series){const {ctx,w,h}=canvasFit(canvas);ctx.clearRect(0,0,w,h);ctx.fillStyle='#0d1626';ctx.fillRect(0,0,w,h);const pad=34,pts=world?.archive?.flattened(1800)||[];if(pts.length<2){ctx.strokeStyle='rgba(56,189,248,.10)';ctx.lineWidth=1;for(let x=pad;x<w;x+=44){ctx.beginPath();ctx.moveTo(x,12);ctx.lineTo(x,h-18);ctx.stroke();}for(let y=24;y<h;y+=34){ctx.beginPath();ctx.moveTo(12,y);ctx.lineTo(w-12,y);ctx.stroke();}ctx.textAlign='center';ctx.fillStyle='#cbd5e1';ctx.font=`${13*(devicePixelRatio||1)}px Arial`;ctx.fillText('הגרף יופיע כשההרצה תצבור היסטוריה',w/2,h/2-4);ctx.fillStyle='#64748b';ctx.font=`${11*(devicePixelRatio||1)}px Arial`;ctx.fillText('הפעל את העולם למספר צעדים',w/2,h/2+18);ctx.textAlign='start';return;}const xs=pts.map(p=>p.tick);let vals=[];for(const s of series)for(const p of pts){const v=s.get(p);if(Number.isFinite(v))vals.push(v);}if(!vals.length)return;let min=Math.min(...vals),max=Math.max(...vals);if(min===max){min-=1;max+=1;}const x0=Math.min(...xs),x1=Math.max(...xs)||1;ctx.strokeStyle='#334155';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,8);ctx.lineTo(pad,h-pad);ctx.lineTo(w-8,h-pad);ctx.stroke();ctx.fillStyle='#94a3b8';ctx.font=`${11*(devicePixelRatio||1)}px Arial`;ctx.fillText(fmt(max,2),3,15);ctx.fillText(fmt(min,2),3,h-pad);for(const s of series){ctx.strokeStyle=s.color;ctx.lineWidth=1.7*(devicePixelRatio||1);ctx.beginPath();let started=false;for(const p of pts){const v=s.get(p);if(!Number.isFinite(v))continue;const x=pad+(p.tick-x0)/(x1-x0||1)*(w-pad-10),y=8+(max-v)/(max-min)*(h-pad-16);if(!started){ctx.moveTo(x,y);started=true;}else ctx.lineTo(x,y);}ctx.stroke();}let lx=pad+5;for(const s of series){ctx.fillStyle=s.color;ctx.fillRect(lx,10,9,9);ctx.fillStyle='#cbd5e1';ctx.fillText(s.name,lx+13,19);lx+=ctx.measureText(s.name).width+36;}}
function updateCharts(){if(!world)return;chart($('chartPop'),[{name:'אוכלוסייה',color:'#38bdf8',get:p=>p.population},{name:'דור חציוני',color:'#fbbf24',get:p=>p.medianGeneration}]);chart($('chartGenetic'),[{name:'מרחק',color:'#f472b6',get:p=>p.meanGeneticDistance},{name:'מגוון',color:'#a78bfa',get:p=>p.geneticDiversity}]);chart($('chartFitness'),[{name:'קצב רבייה',color:'#4ade80',get:p=>p.reproductionRatePer1000MatureTicks},{name:'מספר צאצאים לאורך החיים',color:'#fbbf24',get:p=>p.completedLRS}]);chart($('chartComplex'),[{name:'מוח',color:'#38bdf8',get:p=>p.brainComplexity},{name:'חדשנות',color:'#f472b6',get:p=>p.phenotypeNovelty},{name:'אשכולות',color:'#fbbf24',get:p=>p.observerClusters}]);chart($('chartMorph'),[{name:'רדיוס',color:'#38bdf8',get:p=>p.phenotype?.radius},{name:'חילוף חומרים',color:'#fb7185',get:p=>p.phenotype?.baseMet},{name:'עוצמת מנוע',color:'#4ade80',get:p=>p.traits?.motorPower}]);chart($('chartMaterials'),[{name:'חומר ראשוני',color:COLORS.primary,get:p=>p.materials?.primary},{name:'פסולת',color:COLORS.waste,get:p=>p.materials?.waste},{name:'רקמה',color:COLORS.tissue,get:p=>p.materials?.tissue}]);}

function updateEvolutionUi(){const m=lastMetrics;if(!m)return;const ms=m.mutationStats||{};$('mutationSummary').innerHTML=rowsHtml([['לידות עם מוטציה',fmt(ms.birthsWithMutations,0)],['שינויים גנטיים',fmt(ms.totalChanges,0)],['תכונה',fmt(ms.byType?.trait,0)],['חיישן',fmt(ms.byType?.sensor,0)],['משקל',fmt(ms.byType?.weight,0)],['הטיה',fmt(ms.byType?.bias,0)],['מבני',fmt(ms.byType?.structure,0)],['שיעור מוטציות ממוצע',fmt(m.traits.mutationRate,5)],['שיעור שינוי מבני ממוצע',fmt(m.traits.structuralRate,5)]]);$('brainPopulation').innerHTML=rowsHtml([['חיישני קרניים',fmt(m.avgSensors,2)],['תאים פנימיים',fmt(m.avgHidden,2)],['קשרים',fmt(m.avgConnections,2)],['מורכבות המוח',fmt(m.brainComplexity,2)],['שיעור גנומים ייחודיים',pct(m.uniqueGenomeFraction)],['שיעור הגנום הנפוץ',pct(m.topGenomeShare)]]);$('traitSummary').innerHTML=rowsHtml([['רדיוס',fmt(m.phenotype.radius,3)],['מסה',fmt(m.phenotype.mass,2)],['קיבולת אנרגיה',fmt(m.phenotype.energyCapacity,2)],['מטבוליזם בסיסי',fmt(m.phenotype.baseMet,5)],['מהירות פיזיקלית',fmt(m.phenotype.maxSpeed,3)],['בגרות',fmt(m.phenotype.maturity,1)],['שריון',fmt(m.traits.armor,3)],['תיקון',fmt(m.traits.repair,3)],['עיכול חומר ראשוני',fmt(m.traits.digestPrimary,3)],['עיכול פסולת',fmt(m.traits.digestWaste,3)],['עיכול רקמה',fmt(m.traits.digestTissue,3)]]);
  const gmap=new Map();for(const a of world.agents){const h=E.genomeHash(a.genome),x=gmap.get(h)||{n:0,g:0};x.n++;x.g+=a.generation;gmap.set(h,x);}const arr=[...gmap].sort((a,b)=>b[1].n-a[1].n).slice(0,20);$('genomeTable').innerHTML=arr.map(([h,x])=>`<tr><td class="mono">${h}</td><td>${x.n}</td><td>${pct(x.n/Math.max(1,world.agents.length))}</td><td>${fmt(x.g/x.n,1)}</td></tr>`).join('');
  const ev=world.recentEvents.filter(e=>e.type==='birth'&&e.mutations?.length).slice(-20).reverse();$('mutationEvents').innerHTML=ev.length?ev.map(e=>`<div class="event mut"><div class="t">צעד ${fmt(e.tick,0)} · צאצא ${e.child} · דור ${e.generation}</div><b>${e.mutations.length} שינויים</b> — ${e.mutations.slice(0,4).map(x=>heKey(x.action||x.type)+':'+heKey(x.target)).join(', ')}</div>`).join(''):'<div class="small">עדיין אין אירועי מוטציה.</div>';
}

function brainNodes(g){return{inputs:['energy','health','touch','chemical',...g.sensors.map(s=>'ray:'+s.id)],hidden:g.hidden.map(h=>h.id),outputs:['act:left_motor','act:right_motor','act:jaw','act:grip','act:chemical_emit']};}
function drawBrainMini(){
  const c=$('brainMiniCanvas');if(!c||!world)return;const {ctx,w,h}=canvasFit(c),a=selectedAgent();ctx.clearRect(0,0,w,h);ctx.fillStyle='#101827';ctx.fillRect(0,0,w,h);
  if(!a){ctx.fillStyle='#94a3b8';ctx.font=`${13*(devicePixelRatio||1)}px Arial`;ctx.textAlign='center';ctx.fillText('בחר סומיק כדי לראות את המוח',w/2,h/2);ctx.textAlign='start';return;}
  const g=a.genome,nodes=brainNodes(g),pad=24*(devicePixelRatio||1),pos=new Map();function place(list,x){list.forEach((id,i)=>pos.set(id,{x,y:pad+(i+1)*(h-2*pad)/(list.length+1)}));}
  place(nodes.inputs,pad+13*(devicePixelRatio||1));place(nodes.hidden,w/2);place(nodes.outputs,w-pad-13*(devicePixelRatio||1));const maxW=Math.max(.1,...g.connections.filter(x=>x.enabled).map(x=>Math.abs(x.weight)));
  for(const cn of g.connections){if(!cn.enabled)continue;const p1=pos.get(cn.from),p2=pos.get(cn.to);if(!p1||!p2)continue;ctx.strokeStyle=cn.weight>=0?'rgba(56,189,248,.42)':'rgba(244,114,182,.42)';ctx.lineWidth=(.35+1.5*Math.abs(cn.weight)/maxW)*(devicePixelRatio||1);ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke();}
  for(const [id,p] of pos){let act=0;if(id.startsWith('act:'))act=a.outputs?.[id.slice(4)]||0;else if(id.startsWith('ray:')||['energy','health','touch','chemical'].includes(id))act=a.lastInputs?.[id]||0;else act=a.hiddenState?.[id]||0;const rr=(id.startsWith('ray:')||['energy','health','touch','chemical'].includes(id)?4.5:6)*(devicePixelRatio||1);ctx.fillStyle=act>=0?`rgba(56,189,248,${.30+.60*Math.min(1,Math.abs(act))})`:`rgba(244,114,182,${.30+.60*Math.min(1,Math.abs(act))})`;ctx.strokeStyle='#e2e8f0';ctx.lineWidth=.7*(devicePixelRatio||1);ctx.beginPath();ctx.arc(p.x,p.y,rr,0,Math.PI*2);ctx.fill();ctx.stroke();}
}
function brainLabel(id){
 const key=id.replace('act:','');
 const labels={energy:'אנרגיה',health:'בריאות',touch:'מגע',chemical:'שדה כימי',left_motor:'מנוע שמאל',right_motor:'מנוע ימין',jaw:'לסת',grip:'אחיזה',chemical_emit:'פליטה כימית'};
 if(labels[key])return labels[key];
 if(key.startsWith('ray:'))return 'חיישן '+key.slice(4).replace(/^r/,'');
 if(/^h\d+$/.test(key))return 'תא '+key.slice(1);
 return key;
}
function drawBrain(){if(!world)return;const g=currentGenome();if(!g)return;const c=$('brainCanvas'),{ctx,w,h}=canvasFit(c),nodes=brainNodes(g),pad=48;ctx.clearRect(0,0,w,h);ctx.fillStyle='#0d1626';ctx.fillRect(0,0,w,h);const pos=new Map();function place(list,x){list.forEach((id,i)=>pos.set(id,{x,y:pad+(i+1)*(h-2*pad)/(list.length+1)}));}place(nodes.inputs,pad+30);place(nodes.hidden,w/2);place(nodes.outputs,w-pad-30);const maxW=Math.max(.1,...g.connections.map(c=>Math.abs(c.weight)));for(const cn of g.connections){if(!cn.enabled)continue;const a=pos.get(cn.from),b=pos.get(cn.to);if(!a||!b)continue;ctx.strokeStyle=cn.weight>=0?'rgba(56,189,248,.65)':'rgba(244,114,182,.65)';ctx.lineWidth=(.5+3*Math.abs(cn.weight)/maxW)*(devicePixelRatio||1);ctx.beginPath();ctx.moveTo(a.x,a.y);const mx=(a.x+b.x)/2;ctx.bezierCurveTo(mx,a.y,mx,b.y,b.x,b.y);ctx.stroke();}
  const live=brainMode==='selected'?selectedAgent():null;for(const [id,p] of pos){let act=0;if(live){if(id.startsWith('act:'))act=live.outputs[id.slice(4)]||0;else if(id.startsWith('ray:')||['energy','health','touch','chemical'].includes(id))act=live.lastInputs?.[id]||0;else act=live.hiddenState?.[id]||0;}const rr=id.startsWith('ray:')||['energy','health','touch','chemical'].includes(id)?7:id.startsWith('act:')?9:9;ctx.fillStyle=act>=0?`rgba(56,189,248,${.25+.65*Math.min(1,Math.abs(act))})`:`rgba(244,114,182,${.25+.65*Math.min(1,Math.abs(act))})`;ctx.strokeStyle='#e2e8f0';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,rr*(devicePixelRatio||1),0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#cbd5e1';ctx.font=`${10*(devicePixelRatio||1)}px Arial`;ctx.textAlign=id.startsWith('act:')?'right':id.startsWith('ray:')||['energy','health','touch','chemical'].includes(id)?'left':'center';const label=brainLabel(id);ctx.fillText(label,p.x+(ctx.textAlign==='left'?12:ctx.textAlign==='right'?-12:0)*(devicePixelRatio||1),p.y-11*(devicePixelRatio||1));}ctx.textAlign='start';updateBrainDetails();}
function updateBrainDetails(){if(!world)return;const g=currentGenome(),a=selectedAgent(),found=world.ancestorGenome;if(!g)return;const enabled=g.connections.filter(c=>c.enabled),gd=E.genomeDistance(g,found);$('brainDetails').innerHTML=rowsHtml([['מצב',brainMode==='founder'?'אב קדמון':a?`סומיק #${a.id}`:'אב קדמון'],['חתימה גנטית',E.genomeHash(g),'mono'],['מרחק מהאב',fmt(gd,6)],['חיישנים',g.sensors.length],['תאים פנימיים',g.hidden.length],['קשרים פעילים',enabled.length],['שיעור מוטציות',fmt(g.traits.mutationRate,6)],['שיעור שינוי מבני',fmt(g.traits.structuralRate,6)]]);const fm=new Map(found.connections.map(c=>[c.id,c]));const changed=enabled.map(c=>({c,d:c.weight-(fm.get(c.id)?.weight||0),exists:fm.has(c.id)})).filter(x=>!x.exists||Math.abs(x.d)>1e-6).sort((a,b)=>Math.abs(b.d)-Math.abs(a.d)).slice(0,120);$('connectionTable').innerHTML=changed.map(x=>`<tr><td class="mono">${x.c.id}</td><td>${brainLabel(x.c.from)}</td><td>${brainLabel(x.c.to)}</td><td>${fmt(x.c.weight,4)}</td><td>${x.exists?fmt(x.d,4):'חדש'}</td></tr>`).join('');$('connectionSelect').innerHTML=enabled.slice().sort((a,b)=>Math.abs(b.weight)-Math.abs(a.weight)).map(c=>`<option value="${c.id}">קשר ${c.id.replace(/^c/,'')}: ${brainLabel(c.from)} ← ${brainLabel(c.to)} (${fmt(c.weight,3)})</option>`).join('');}

function drawLineage(){const c=$('lineageCanvas'),{ctx,w,h}=canvasFit(c);ctx.clearRect(0,0,w,h);ctx.fillStyle='#0d1626';ctx.fillRect(0,0,w,h);const root=selectedAgent();if(!root){ctx.fillStyle='#94a3b8';ctx.fillText('בחר סומיק',20,30);return;}const byId=world.lineageRecent;const levels=[[root]],seen=new Set([root.id]);for(let d=1;d<6;d++){const prev=levels[d-1],cur=[];for(const x of prev){const rec=x.kind==='agent'?x:byId.get(x.id);for(const pid of [rec?.parentA,rec?.parentB])if(pid&&!seen.has(pid)&&byId.has(pid)){seen.add(pid);cur.push(byId.get(pid));}}if(!cur.length)break;levels.push(cur);}const pos=new Map();for(let d=0;d<levels.length;d++){const list=levels[d];for(let i=0;i<list.length;i++){const x=w/2+(i-(list.length-1)/2)*Math.min(90,w/Math.max(2,list.length+1)),y=35+d*(h-60)/Math.max(1,levels.length-1);pos.set(list[i].id,{x,y});}}ctx.strokeStyle='#64748b';for(let d=0;d<levels.length-1;d++)for(const x of levels[d]){const rec=x.kind==='agent'?x:byId.get(x.id),p=pos.get(x.id);for(const pid of [rec?.parentA,rec?.parentB])if(pos.has(pid)){const q=pos.get(pid);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();}}for(const [id,p] of pos){ctx.fillStyle=id===root.id?'#fff':'#38bdf8';ctx.beginPath();ctx.arc(p.x,p.y,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#cbd5e1';ctx.font='10px Arial';ctx.fillText('#'+id,p.x+8,p.y+3);}}
function updateLineages(){if(!world)return;drawLineage();const rows=[];const bins=Object.keys(world.cohortStats).map(Number).sort((a,b)=>a-b).slice(-8);for(const bin of bins){const c=world.cohortStats[bin],birthTotal=Object.values(c.birthAncestry||{}).reduce((a,b)=>a+b,0),expTotal=Object.values(c.eligibleExposure||{}).reduce((a,b)=>a+b,0);const keys=new Set([...Object.keys(c.birthAncestry||{}),...Object.keys(c.eligibleExposure||{})]);for(const k of keys){const bs=(c.birthAncestry?.[k]||0)/Math.max(1e-9,birthTotal),es=(c.eligibleExposure?.[k]||0)/Math.max(1e-9,expTotal);if(es<0.01)continue;rows.push({bin,k,bs,es,rf:bs/es});}}rows.sort((a,b)=>b.bin-a.bin||b.rf-a.rf);$('lineageFitnessTable').innerHTML=rows.slice(0,80).map(x=>`<tr><td>${x.bin}–${x.bin+49}</td><td>${x.k}</td><td>${pct(x.bs,2)}</td><td>${pct(x.es,2)}</td><td>${fmt(x.rf,3)}</td></tr>`).join('');const mass={};for(const a of world.agents)for(const[k,v]of Object.entries(a.ancestry||{}))mass[k]=(mass[k]||0)+v;const total=world.agents.length||1;$('founderAncestry').innerHTML=Object.entries(mass).sort((a,b)=>b[1]-a[1]).slice(0,15).map(([k,v])=>`<div class="row"><span>מייסד ${k}</span><b>${pct(v/total,2)}</b></div>`).join('')||'<div class="small">—</div>';const ev=world.recentEvents.filter(e=>['birth','death','checkpoint','technical_failure'].includes(e.type)).slice(-40).reverse();$('eventLog').innerHTML=ev.map(e=>`<div class="event ${e.type}"><div class="t">צעד ${fmt(e.tick,0)}</div><b>${heValue(e.type)}</b> ${e.type==='birth'?`צאצא ${e.child} · הורים ${e.parentA}/${e.parentB||'—'} · דור ${e.generation}${e.mutations?.length?` · ${e.mutations.length} מוטציות`:''}`:e.type==='death'?`סומיק ${e.agent} · דור ${e.generation} · צאצאים ${e.offspring}`:e.type==='checkpoint'?`דור ${e.generation}`:(e.message?heError(e.message):'')}</div>`).join('');}

function updateEcologyUi(){const m=lastMetrics;if(!m)return;$('materialsRows').innerHTML=rowsHtml([['חומר ראשוני',fmt(m.materials.primary,2)],['פסולת',fmt(m.materials.waste,2)],['רקמה',fmt(m.materials.tissue,2)],['מסת גופות',fmt(m.corpseBiomass,2)],['משאבים חופשיים',fmt(m.resources,0)],['חפצים',fmt(m.objects,0)]]);const e=m.ecology;$('ecologyRows').innerHTML=rowsHtml([['חומר ראשוני שנצרך',fmt(e.consumedPrimary,2)],['פסולת שנצרכה',fmt(e.consumedWaste,2)],['רקמה שנצרכה',fmt(e.consumedTissue,2)],['נשיכות',fmt(e.bites,0)],['נזק מטריפה',fmt(e.predationDamage,4)],['נזק מאזור הסכנה',fmt(e.hazardDamage,4)],['צעדים באזור הסכנה',fmt(e.hazardTicks,0)],['צעדים מוגנים ליד בלוק',fmt(e.protectedTicks,0)],['מנות מזון שהושארו',fmt(e.foodDropped,0)],['חזרות למזון',fmt(e.foodReturned,0)],['ביקורים ליד מועמד מטמון',fmt(e.cacheVisits,0)],['מזון שאבד',fmt(e.foodStolen,0)],['אחיזות',fmt(e.grips,0)],['צעדי נשיאת חפצים',fmt(e.objectCarryTicks,0)],['פליטה כימית',fmt(e.chemicalEmission,2)],['פסולת שיוצרה',fmt(e.wasteProduced,2)],['גופות שנוצרו',fmt(e.corpsesCreated,0)]]);const b=m.behavior;$('behaviorRows').innerHTML=rowsHtml([['מרחק לכל 1,000 צעדי חיים',fmt(b.distancePer1000Age,2)],['חומר ראשוני לכל 1,000 צעדי חיים',fmt(b.primaryPer1000Age,3)],['פסולת לכל 1,000 צעדי חיים',fmt(b.wastePer1000Age,3)],['רקמה לכל 1,000 צעדי חיים',fmt(b.tissuePer1000Age,3)],['חלק החיים באחיזה',pct(b.gripFraction,2)],['פליטה כימית לכל 1,000 צעדי חיים',fmt(b.chemicalPer1000Age,3)],['נזק שנגרם לאחרים לכל 1,000 צעדים',fmt(b.damageGivenPer1000Age,5)],['נזק שהתקבל לכל 1,000 צעדים',fmt(b.damageTakenPer1000Age,5)]]);const a=selectedAgent();$('selectedEcology').innerHTML=a?rowsHtml([['מרחק חיים',fmt(a.distance,2)],['חומר ראשוני שנאכל',fmt(a.foodPrimary,3)],['פסולת שנאכלה',fmt(a.foodWaste,3)],['רקמה שנאכלה',fmt(a.foodTissue,3)],['נזק שנגרם לאחרים',fmt(a.damageGiven,5)],['נזק שהתקבל',fmt(a.damageTaken,5)],['צעדים באחיזה',fmt(a.gripTicks,0)],['פליטה כימית מצטברת',fmt(a.chemicalTotal,3)],['מוחזק',a.holding?`${heValue(a.holding.kind)} #${a.holding.id}`:'לא']]):'<div class="small">בחר סומיק.</div>';drawTradeoff();}
function drawTradeoff(){const c=$('tradeoffCanvas'),{ctx,w,h}=canvasFit(c),arr=world?.agents||[];ctx.clearRect(0,0,w,h);ctx.fillStyle='#0d1626';ctx.fillRect(0,0,w,h);if(!arr.length)return;const samp=arr.length>300?arr.filter((_,i)=>i%Math.ceil(arr.length/300)===0):arr;const pts=samp.map(a=>({x:a.pheno.baseMet,y:a.pheno.energyCapacity,r:a.pheno.radius})),xmin=Math.min(...pts.map(p=>p.x)),xmax=Math.max(...pts.map(p=>p.x)),ymin=Math.min(...pts.map(p=>p.y)),ymax=Math.max(...pts.map(p=>p.y)),pad=28;ctx.strokeStyle='#334155';ctx.beginPath();ctx.moveTo(pad,8);ctx.lineTo(pad,h-pad);ctx.lineTo(w-8,h-pad);ctx.stroke();for(const p of pts){const x=pad+(p.x-xmin)/(xmax-xmin||1)*(w-pad-10),y=8+(ymax-p.y)/(ymax-ymin||1)*(h-pad-16);ctx.fillStyle='rgba(56,189,248,.55)';ctx.beginPath();ctx.arc(x,y,Math.max(2,p.r*.5),0,Math.PI*2);ctx.fill();}}

