function checkpointGenome(){const cps=Object.values(world.checkpoints||{}).sort((a,b)=>b.generation-a.generation);return cps[0]?.genomes?.[0]||null;}
  function labWorker(){const url=new URL('research-engine.js',location.href).href,engineBootstrap=globalThis.__SOMIK_ENGINE_SOURCE||`importScripts(${JSON.stringify(url)});`;const code=`${engineBootstrap}\nconst E=SomikResearch;onmessage=e=>{const m=e.data;try{let r;if(m.cmd==='selftest'){r=E.selfTest();}else if(m.cmd==='assayPair'){const a=E.runAssay(m.ancestor,m.seed,m.opts),b=E.runAssay(m.genome,m.seed,m.opts);r={ancestor:a,evolved:b,ratio:a.reproRate>0?b.reproRate/a.reproRate:null};}else if(m.cmd==='common'){r=E.commonGarden([m.genome],m.ancestor,m.seeds,m.opts);}else if(m.cmd==='neighborhood'){r=E.mutationalNeighborhood(m.genome,m.seed,m.n,m.opts);}else if(m.cmd==='control'){const w=new E.World({seed:m.seed,mutationEnabled:false,reproductionMode:'sexual',objectsEnabled:true,chemicalEnabled:true,hazardEnabled:true,cacheEnabled:true});for(let i=0;i<m.ticks&&!w.extinct&&!w.technicalFailure;i++)w.step();r={metrics:w.metrics(),stateHash:w.stateHash(),uniqueGenomes:new Set(w.agents.map(a=>E.genomeHash(a.genome))).size};}else if(m.cmd==='multiseed'){const rows=[];for(let i=0;i<m.n;i++){const seed=m.base+i;const w=new E.World({seed,hazardEnabled:true,cacheEnabled:true});for(let t=0;t<m.ticks&&!w.extinct&&!w.technicalFailure;t++)w.step();rows.push({seed,...w.metrics(),stateHash:w.stateHash()});}r=rows;}else if(m.cmd==='variant'){const o=m.options||{},w=new E.World({seed:m.seed,mutationEnabled:o.mutationEnabled!==false,reproductionMode:o.reproductionMode||'sexual',objectsEnabled:o.objectsEnabled!==false,chemicalEnabled:o.chemicalEnabled!==false,memoryEnabled:o.memoryEnabled!==false,hazardEnabled:o.hazardEnabled!==false,cacheEnabled:o.cacheEnabled!==false});for(let t=0;t<m.ticks&&!w.extinct&&!w.technicalFailure;t++)w.step();r={treatment:w.treatment,metrics:w.metrics(),stateHash:w.stateHash(),protocolVariantHash:w.protocolVariantHash};}else if(m.cmd==='knockout'){const ko=E.knockoutGenome(m.genome,m.conn);const base=E.runAssay(m.genome,m.seed,m.opts),knock=E.runAssay(ko,m.seed,m.opts);r={base,knockout:knock,ratio:base.reproRate>0?knock.reproRate/base.reproRate:null};}postMessage({ok:true,r});}catch(err){postMessage({ok:false,error:String(err.stack||err)});}}`;const blobUrl=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));const worker=new Worker(blobUrl);worker.sourceUrl=blobUrl;return worker;}
const activeWorkers=new Map();
function runWorker(msg,outId,format=heReport){
  const out=$(outId),previous=activeWorkers.get(outId);if(previous){previous.terminate();URL.revokeObjectURL(previous.sourceUrl);}
  out.textContent='מריץ ניסוי…';let w;
  const finish=()=>{w?.terminate();if(w)URL.revokeObjectURL(w.sourceUrl);activeWorkers.delete(outId);};
  try{w=labWorker();activeWorkers.set(outId,w);
    w.onmessage=e=>{finish();out.textContent=e.data.ok?(msg.cmd==='selftest'?heTests(e.data.r):heReport(e.data.r)):'שגיאה: '+heError(e.data.error);};
    w.onerror=e=>{finish();out.textContent='הניסוי נכשל: '+heError(e);};w.postMessage(msg);
  }catch(err){finish();out.textContent='לא ניתן להריץ ניסוי: '+heError(err);}
}
function assayOpts(){return{ticks:Math.max(500,Number($('assayTicks').value)||4000),founderCount:20,reproductionMode:'asexual',objectsEnabled:false,chemicalEnabled:false};}

function drawBrainAndLineage(){drawBrain();updateLineages();}
function updateProtocolUi(){$('protocolText').textContent=heReport(E.Protocol);updateRunIdentity();}
function runSelfTest(){runWorker({cmd:'selftest'},'selfTestOut',t=>(t.ok?'PASS':'FAIL')+' · '+t.results.length+' checks\n'+t.results.map(x=>`${x.ok?'✓':'✗'} ${x.name}${x.detail?' — '+x.detail:''}`).join('\n'));}

function fullRefresh(){observeLiving();updateMetrics();updateLivingUi();drawWorld();updateCharts();drawBrainAndLineage();updateProtocolUi();refreshArchiveUi();}
function uiRefresh(){observeLiving();updateMetrics();updateLivingUi();drawBrainMini();drawChartsIfVisible();if(document.getElementById('tab-brain').classList.contains('active'))drawBrain();if(document.getElementById('tab-lineages').classList.contains('active'))updateLineages();if(document.getElementById('tab-ecology').classList.contains('active'))drawTradeoff();}
function drawChartsIfVisible(){if($('tab-overview').classList.contains('active'))updateCharts();}

function loop(now){requestAnimationFrame(loop);if(!world)return;let steps=0;if(running&&!world.extinct&&!world.technicalFailure){const target=speed,budget=speed>=500?15:speed>=100?10:8,start=performance.now();while(steps<target&&performance.now()-start<budget){world.step();steps++;if(world.extinct||world.technicalFailure)break;}ticksSincePerf+=steps;if(world.extinct||world.technicalFailure){running=false;updatePauseUi();saveNow(world.extinct?'extinction':'technical-failure');}}
  if(now-lastPerfAt>1000){currentTPS=ticksSincePerf*1000/(now-lastPerfAt);ticksSincePerf=0;lastPerfAt=now;$('computeLine').textContent=`${fmt(currentTPS,0)} צעדים לשנייה · מהירות ×${speed}`;}
  if(!saveInFlight&&(Date.now()-lastAutosaveWall>AUTOSAVE_MS||world.tick-lastAutosaveTick>=AUTOSAVE_TICKS))saveNow('autosave');
  if(now-lastUiAt>500){uiRefresh();lastUiAt=now;}
  if(renderEnabled&&now-lastDrawAt>(speed>=500?250:speed>=100?100:40)){drawWorld();lastDrawAt=now;}
}

async function exportRun(full=false){
  const was=running;running=false;updatePauseUi();try{
    await saveNow('export');
    const state=JSON.parse(JSON.stringify(world.dump()));
    const data={schema:'SomikWorldResearchExport/1.2',exportedAt:nowIso(),runMeta:{...runMeta},protocol:E.Protocol,
      protocolId:E.PROTOCOL_ID,protocolHash:E.PROTOCOL_HASH,engineHash:E.ENGINE_HASH,
      stateHash:world.stateHash(),snapshotHash:E.snapshotHash(state),state,summary:world.metrics()};
    if(full)data.events=[...await getAllEvents(),...importedEvents];
    data.archiveComplete=!!db&&!importedEvents.length&&runMeta.lastSaveTick===world.tick;
    downloadJson(data,`somik-research-${runMeta.runId}-${full?'full-archive':'run'}.json`);
  }finally{running=was&&!world.extinct&&!world.technicalFailure;updatePauseUi();}
}
function downloadJson(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
async function importFile(file){
  const data=JSON.parse(await file.text()),state=data.state||data;
  if(data.snapshotHash&&E.snapshotHash(state)!==data.snapshotHash)throw new Error('Snapshot checksum mismatch');
  const loaded=E.World.load(state);
  if(data.stateHash&&loaded.stateHash()!==data.stateHash)throw new Error('Scientific state checksum mismatch');
  const entries=(data.events||[]).map(compactEvent).filter(Boolean);
  if(entries.some(e=>!Number.isSafeInteger(e.tick)||e.tick<0||e.tick>loaded.tick))throw new Error('Invalid archive event');
  const was=running;running=false;if(db&&!await saveNow('before-import')){running=was;throw new Error('Save failed; current run retained');}
  world=loaded;importedEvents=entries;runMeta={runId:makeRunId(world.seed),sourceRunId:data.runMeta?.runId||null,
    createdAt:nowIso(),lastSaveAt:'',lastSaveTick:-1,eventSeq:0,archiveOrigin:data.events?'imported-full':'snapshot-only'};
  selectedId=null;resetLivingObserver();running=false;lastAutosaveWall=Date.now();lastAutosaveTick=world.tick;
  $('seedInput').value=world.seed;updatePauseUi();updateRunIdentity();fullRefresh();await saveNow('import');
}

function bind(){
  $('openV3Btn').onclick=()=>{if(globalThis.__SOMIK_V3_SOURCE){const u=URL.createObjectURL(new Blob([globalThis.__SOMIK_V3_SOURCE],{type:'text/html'}));window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000);}else window.open('v3-baseline.html','_blank','noopener');};
  $('pauseBtn').onclick=()=>{running=!running&&!world.extinct&&!world.technicalFailure;updatePauseUi();};$('speedSel').onchange=e=>speed=Number(e.target.value)||1;$('renderBtn').onclick=()=>{renderEnabled=!renderEnabled;$('renderBtn').textContent=`👁 תצוגה: ${renderEnabled?'פעילה':'חסכונית'}`;if(renderEnabled)drawWorld();};$('saveBtn').onclick=()=>saveNow('manual');$('exportBtn').onclick=()=>exportRun(false);$('exportFullBtn').onclick=()=>exportRun(true);$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{try{if(e.target.files[0])await importFile(e.target.files[0]);}catch(err){alert(heError(err));}e.target.value='';};$('newRunBtn').onclick=async()=>{if(!confirm('לשמור את ה־עולם הנוכחי וליצור עולם חדש?'))return;running=false;if(db&&!await saveNow('before-new-run')){updatePauseUi();return;}newWorld(Number($('seedInput').value)||1);};$('world').addEventListener('click',worldClick);if($('openBrainTabBtn'))$('openBrainTabBtn').onclick=()=>{const b=document.querySelector('.tabBtn[data-tab="brain"]');if(b){b.click();setTimeout(()=>document.getElementById('tab-brain')?.scrollIntoView({behavior:'smooth',block:'start'}),40);}};
  document.querySelectorAll('.tabBtn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabBtn').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.tabPane').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('tab-'+b.dataset.tab).classList.add('active');setTimeout(()=>{uiRefresh();drawBrainAndLineage();},20);});
  $('brainSelectedBtn').onclick=()=>{brainMode='selected';drawBrain();};$('brainFounderBtn').onclick=()=>{brainMode='founder';drawBrain();};$('knockoutBtn').onclick=()=>{const g=currentGenome(),conn=$('connectionSelect').value;if(!g||!conn)return;runWorker({cmd:'knockout',genome:g,conn,seed:93001,opts:assayOpts()},'commonGardenOut');};$('commonGardenBtn').onclick=()=>{const a=selectedAgent();if(!a)return $('commonGardenOut').textContent='בחר סומיק.';runWorker({cmd:'common',genome:a.genome,ancestor:world.ancestorGenome,seeds:[91001,91002,91003,91004,91005],opts:assayOpts()},'commonGardenOut',r=>`Mean ratio evolved/ancestor: ${fmt(r.meanRatio,4)}\nMean log ratio: ${fmt(r.meanLogRatio,4)}\n\n`+JSON.stringify(r.ratios,null,2));};$('ancestorReplayBtn').onclick=()=>{const a=selectedAgent();if(!a)return $('commonGardenOut').textContent='בחר סומיק.';runWorker({cmd:'assayPair',genome:a.genome,ancestor:world.ancestorGenome,seed:92001,opts:assayOpts()},'commonGardenOut');};$('mutationOffBtn').onclick=()=>runWorker({cmd:'control',seed:world.seed,ticks:Math.max(500,Number($('controlTicks').value)||5000)},'mutationOffOut',r=>`Mutation-Off · same seed ${world.seed}\nUnique genomes alive: ${r.uniqueGenomes}\nState hash: ${r.stateHash}\n\n${JSON.stringify(r.metrics,null,2)}`);$('neighborhoodBtn').onclick=()=>{const a=selectedAgent();if(!a)return $('neighborhoodOut').textContent='בחר סומיק.';runWorker({cmd:'neighborhood',genome:a.genome,seed:99001,n:Number($('mutantN').value)||48,opts:{ticks:2500,founderCount:14}},'neighborhoodOut',r=>`Beneficial >1.02: ${r.beneficial}\nNeutral 0.98–1.02: ${r.neutral}\nDeleterious <0.98: ${r.deleterious}\nMean relative: ${fmt(r.meanRelative,4)}\n\n${JSON.stringify(r.rows.slice(0,40),null,2)}`);};$('multiSeedBtn').onclick=()=>runWorker({cmd:'multiseed',base:200001,n:Number($('multiN').value)||5,ticks:Number($('multiTicks').value)||4000},'multiOut',r=>r.map(x=>`Seed ${x.seed}: pop=${x.population} gen=${fmt(x.medianGeneration,1)} repro=${fmt(x.reproductionRatePer1000MatureTicks,4)} dist=${fmt(x.meanGeneticDistance,4)} extinct=${x.extinct}`).join('\n'));$('treatmentBtn').onclick=()=>runWorker({cmd:'variant',seed:world.seed,ticks:Math.max(100,Number($('treatmentTicks').value)||2000),options:{mutationEnabled:$('tMutation').checked,reproductionMode:$('tAsexual').checked?'asexual':'sexual',objectsEnabled:$('tObjects').checked,chemicalEnabled:$('tChemical').checked,memoryEnabled:$('tMemory').checked}},'treatmentOut',r=>`Variant ${r.protocolVariantHash}\n${JSON.stringify(r.treatment,null,2)}\n\n${JSON.stringify(r.metrics,null,2)}\nState hash: ${r.stateHash}`);$('ancestryBtn').onclick=reconstructAncestry;$('persistStorageBtn').onclick=requestPersistentStorage;$('selfTestBtn').onclick=runSelfTest;
  addEventListener('beforeunload',()=>{try{saveNow('beforeunload');}catch{}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveNow('hidden');});
}

async function init(){
  bind();try{db=await openDb();}catch(err){db=null;$('saveStatus').className='saveWarn';$('saveStatus').textContent='אחסון מקומי אינו זמין — השתמש בייצוא קובץ לגיבוי.';}
  const rec=db?await latestSnapshot():null;
  if(rec){try{await loadSnapshotRecord(rec);running=false;updatePauseUi();$('saveStatus').className='saveOk';$('saveStatus').textContent=`✓ שוחזר צעד ${fmt(rec.tick,0)} — לחץ הפעל להמשך`;}
    catch(err){$('saveStatus').textContent='שמירה לא תואמת: '+heError(err);running=false;world=null;throw err;}}
  else newWorld(1);
  $('selfTestOut').textContent='לחץ להרצת בדיקות הליבה בעולם נפרד.';
  requestAnimationFrame(loop);
}
init().catch(err=>{console.error(err);$('saveStatus').className='saveWarn';$('saveStatus').textContent='האתחול נכשל: '+heError(err);});
